# Analyze components within each strict quadrant
from collections import deque
for name, pts in [('UL',[(r,c) for r,c in coords if r<9 and c<9]),('UR',[(r,c) for r,c in coords if r<9 and c>9]),('LL',[(r,c) for r,c in coords if r>9 and c<9]),('LR',[(r,c) for r,c in coords if r>9 and c>9])]:
    s=set(pts); comps=[]
    while s:
        p=s.pop(); comp={p}; q=[p]
        while q:
            r,c=q.pop()
            for z in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                if z in s: s.remove(z); comp.add(z); q.append(z)
        comps.append(comp)
    print(name, [sorted(x) for x in comps])

out2=[[1]*18 for _ in range(18)]
for r in range(13): out2[r][9]=2
for c in range(8,18): out2[9][c]=2
for r,c in coords:
    if r==9 or c==9: out2[r][c]=7
for name,pts,corner in [('UL',[(r,c) for r,c in coords if r<9 and c<9],'tl'),('UR',[(r,c) for r,c in coords if r<9 and c>9],'tr'),('LL',[(r,c) for r,c in coords if r>9 and c<9],'bl'),('LR',[(r,c) for r,c in coords if r>9 and c>9],'br')]:
 s=set(pts)
 while s:
  p=s.pop(); comp={p}; q=[p]
  while q:
   r,c=q.pop()
   for z in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
    if z in s: s.remove(z);comp.add(z);q.append(z)
  minr=min(r for r,c in comp);maxr=max(r for r,c in comp);minc=min(c for r,c in comp);maxc=max(c for r,c in comp)
  dr=-minr if corner[0]=='t' else 17-maxr
  dc=-minc if corner[1]=='l' else 17-maxc
  for r,c in comp: out2[r+dr][c+dc]=7
print('\n'.join(' '.join(map(str,row)) for row in out2))

# Start from original sets coords, marker ray trans operator operating on current 7 mask only
N=18
orig7=set(coords)
def transform(gs, axis, cut, side):
    # axis horizontal: cut row; marker side left/right; output destinations top/bottom plus marker side
    res=set((r,c) for r,c in gs if (r==cut if axis=='h' else c==cut))
    if axis=='h':
        upper=[p for p in gs if p[0]<cut]; lower=[p for p in gs if p[0]>cut]
        for pts, vertical in [(upper,'top'),(lower,'bottom')]:
            if not pts: continue
            minr=min(r for r,c in pts);maxr=max(r for r,c in pts);minc=min(c for r,c in pts);maxc=max(c for r,c in pts)
            dr=-minr if vertical=='top' else N-1-maxr
            dc=-(minc) if side=='left' else N-1-maxc
            res.update((r+dr,c+dc) for r,c in pts)
    else:
        left=[p for p in gs if p[1]<cut]; right=[p for p in gs if p[1]>cut]
        for pts, horizontal in [(left,'left'),(right,'right')]:
            if not pts: continue
            minr=min(r for r,c in pts);maxr=max(r for r,c in pts);minc=min(c for r,c in pts);maxc=max(c for r,c in pts)
            dr=-(minr) if side=='top' else N-1-maxr
            dc=-(minc) if horizontal=='left' else N-1-maxc
            res.update((r+dr,c+dc) for r,c in pts)
    return res
for sequence in [('v','h'),('h','v')]:
 gs=orig7.copy()
 for x in sequence:
  if x=='v': gs=transform(gs,'v',9,'top')
  else: gs=transform(gs,'h',9,'right')
 print(sequence,len(gs), sorted(gs))

